import java.util.Properties;
import java.util.function.Consumer;

/**
 * Unit tests for CommandLine.getParsedOptionValue(OptionGroup, Supplier)
 */
class CommandLine_getParsedOptionValue_34_0_Test {

    @Test
    void testNullOptionGroupReturnsDefault() throws Exception {
        // Arrange
        // protected ctor accessible in same package
        CommandLine cmd = new CommandLine();
        Supplier<String> defaultSupplier = () -> "DEFAULT";
        // Use reflection to get method (demonstrates reflective invocation)
        Method m = CommandLine.class.getMethod("getParsedOptionValue", OptionGroup.class, Supplier.class);
        m.setAccessible(true);
        // Act
        Object result = m.invoke(cmd, (OptionGroup) null, defaultSupplier);
        // Assert
        assertEquals("DEFAULT", result);
    }

    @Test
    void testUnselectedOptionGroupReturnsDefault() throws Exception {
        // Arrange
        CommandLine cmd = new CommandLine();
        // by default not selected
        OptionGroup group = new OptionGroup();
        Supplier<Integer> defaultSupplier = () -> 42;
        Method m = CommandLine.class.getMethod("getParsedOptionValue", OptionGroup.class, Supplier.class);
        m.setAccessible(true);
        // Act
        Object result = m.invoke(cmd, group, defaultSupplier);
        // Assert
        assertEquals(42, result);
    }

    @Test
    void testSelectedOptionGroupDelegatesToStringOverloadAndReturnsDefaultWhenOptionMissing() throws Exception {
        // Arrange
        CommandLine cmd = new CommandLine();
        OptionGroup group = new OptionGroup();
        // set private field 'selected' on OptionGroup via reflection to mark it selected
        Field selectedField = OptionGroup.class.getDeclaredField("selected");
        selectedField.setAccessible(true);
        selectedField.set(group, "nonExistingOption");
        // Ensure isSelected() returns true now
        assertTrue(group.isSelected());
        Supplier<String> defaultSupplier = () -> "FALLBACK";
        // Invoke focal method reflectively
        Method m = CommandLine.class.getMethod("getParsedOptionValue", OptionGroup.class, Supplier.class);
        m.setAccessible(true);
        Object result = m.invoke(cmd, group, defaultSupplier);
        // Depending on internal implementation of the String overload this test
        // asserts that when the selected name does not correspond to a real option,
        // the default supplier is used (no exception is thrown).
        assertEquals("FALLBACK", result);
    }
}
